// The level list of "Distinguish" (web/src/kernels/gpt.levels.json, generated by
// numerics/gpt/generate.jl): every level passes the kernel's own verification and equals
// the level cases of the Julia golden file.
//
// GPT_LEVELS=<path> checks another level file (the red corpus tests/red/c02-game/ plants a
// wrong stored optimum and an unsolvable level this way); GPT_KERNEL as in gpt.test.ts.
import fs from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { loadGolden } from '../golden';

type Kernel = typeof import('../../src/kernels/gpt');
const K: Kernel = process.env.GPT_KERNEL ? await import(path.resolve(process.env.GPT_KERNEL)) : await import('../../src/kernels/gpt');
const levels = process.env.GPT_LEVELS
  ? K.parseLevels(JSON.parse(fs.readFileSync(path.resolve(process.env.GPT_LEVELS), 'utf8')))
  : [...K.LEVELS];

interface LevelCase { kind: string; id: string; theory: string; omega_1: string[]; omega_2: string[]; priors: string[]; p_opt: unknown; optimal_extreme_effects: unknown[]; all_effects_optimal: boolean }

describe('levels of c02.demo.distinguish', () => {
  it('there are levels', () => { expect(levels.length).toBeGreaterThan(0); });
  for (const l of levels) {
    it(`level ${l.id} is consistent: states in K, optimal effects in E(K) and extreme, stored P_opt = computed optimum`, () => {
      K.verifyLevel(l);
    });
  }
  it('the level list is the first-release list of the reference, in its order, value for value', () => {
    const golden = loadGolden<LevelCase>('gpt').cases.filter((c) => c.kind === 'level');
    expect(levels.map((l) => l.id)).toEqual(golden.map((c) => c.id));
    expect(levels.map((l) => l.id)).toEqual(['B1', 'B2', 'S1', 'S2', 'Q1', 'Q2']);
    for (const c of golden) {
      const l = levels.find((x) => x.id === c.id)!;
      expect(l.theory.id).toBe(c.theory);
      expect(K.vecToStrings(l.problem.omega1)).toEqual(c.omega_1);
      expect(K.vecToStrings(l.problem.omega2)).toEqual(c.omega_2);
      expect([K.ratToString(l.problem.pi1), K.ratToString(l.problem.pi2)]).toEqual(c.priors);
      expect(K.surdToJSON(l.pOpt), `level ${c.id}: stored P_opt against the reference`).toEqual(c.p_opt);
      expect(l.optimal.map(K.effectToJSON)).toEqual(c.optimal_extreme_effects);
      expect(l.allOptimal).toBe(c.all_effects_optimal);
      expect(l.derivation).toContain(`DERIVATION.md section 5.1, row ${c.id}`);
    }
  });
  it('the sequence contains the four kinds of level the game is built on', () => {
    const by = (id: string) => levels.find((l) => l.id === id)!;
    const one = K.surd(K.ONE);
    // a pair that is perfectly distinguishable in the square bit
    expect(by('S1').theory.id === 'square_bit' && K.surdEq(by('S1').pOpt, one)).toBe(true);
    // a tie between two extreme effects
    expect(by('S2').optimal.length).toBe(2);
    // pure qubit states that are not perfectly distinguishable
    expect(by('Q1').theory.id === 'qubit_ball' && K.cmpSurd(by('Q1').pOpt, one) < 0).toBe(true);
    // guessing is optimal: the unit effect, P_opt = max(pi_1, pi_2)
    expect(K.effectsEqual(by('Q2').optimal[0], K.unitEffect(by('Q2').theory)) && K.cmpSurd(by('Q2').pOpt, K.surd(K.guessScore(by('Q2').problem))) === 0).toBe(true);
  });
});
